@Configuration
public class AppConfig {

    @Bean
    public Counter counterA() {
        return new Counter("A");
    }

    @Bean
    public Counter counterB() {
        Counter twin = counterA();
        twin.reset();
        return new Counter("B");
    }

    @Service
    static class AuditService {
        AuditService(Counter counterA) {
            System.out.println("审计拿到: " + counterA.name());
        }
    }

    static class Counter {
        private final String name;
        Counter(String name) { this.name = name; }
        String name() { return name; }
        void reset() { System.out.println("重置 " + name); }
    }
}
